#!/bin/bash
# Compile TuiMain.swift into Warden.app - a macOS app that Dock,
# Command-Tab, `open -a` and AppleScript can all bring to the front.
# Generated by `repl-kit app init`.
#
#   ./app/build.sh                      # build app/Warden.app
#   ./app/build.sh --out ~/Applications/Warden.app
#
# Needs swiftc (ships with the Xcode Command Line Tools: xcode-select --install)
# plus the macOS built-ins osascript / codesign / lsregister.
#
# Why not an `osacompile` AppleScript applet: an applet has no `activate` hook, so
# the Dock icon works and Command-Tab leaves an empty window on top.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$HERE/.." && pwd)"
SRC="$HERE/TuiMain.swift"
OUT="$HERE/Warden.app"
ICNS="$HERE/warden.icns"
BUNDLE_ID="com.ti-extend.warden"

while [ $# -gt 0 ]; do
    case "$1" in
        --out) OUT="${2:?--out needs a path}"; shift 2 ;;
        --out=*) OUT="${1#*=}"; shift ;;
        --icon) ICNS="${2:?--icon needs a path}"; shift 2 ;;
        --icon=*) ICNS="${1#*=}"; shift ;;
        -h|--help) sed -n '2,15p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
        *) echo "unknown argument: $1" >&2; exit 2 ;;
    esac
done

# ---- preflight ------------------------------------------------------------
[ -f "$SRC" ] || { echo "✗ missing $SRC - rerun \`repl-kit app init\`" >&2; exit 2; }
if ! command -v swiftc >/dev/null 2>&1; then
    cat >&2 <<'EOF'
✗ no swiftc. Install the Command Line Tools:

      xcode-select --install

  (it opens a GUI dialog; there is no way to install this absolutely)
EOF
    exit 2
fi
# The repo path goes into a Swift string literal.
case "$REPO" in
    *'"'*|*'\\'*) echo "✗ repo path contains \" or \\, cannot inline it: $REPO" >&2; exit 2 ;;
esac

echo "→ repo:   $REPO"
echo "→ output: $OUT"

# ---- bundle ---------------------------------------------------------------
rm -rf "$OUT"
mkdir -p "$OUT/Contents/MacOS" "$OUT/Contents/Resources"

cat > "$OUT/Contents/Info.plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
<key>CFBundleName</key><string>Warden</string>
<key>CFBundleDisplayName</key><string>Warden</string>
<key>CFBundleIdentifier</key><string>$BUNDLE_ID</string>
<key>CFBundleExecutable</key><string>Warden</string>
<key>CFBundleIconFile</key><string>warden</string>
<key>CFBundlePackageType</key><string>APPL</string>
<key>CFBundleInfoDictionaryVersion</key><string>6.0</string>
<key>CFBundleShortVersionString</key><string>1.0</string>
<key>CFBundleVersion</key><string>1</string>
<key>LSMinimumSystemVersion</key><string>13.0</string>
<key>NSHighResolutionCapable</key><true/>
<key>LSApplicationCategoryType</key><string>public.app-category.productivity</string>
<!-- regular: appear in the Dock and in Command-Tab, which is the point. -->
<key>LSUIElement</key><false/>
<!-- Explains the first "wants to control iTerm2" prompt in its own words. -->
<key>NSAppleEventsUsageDescription</key>
<string>Warden needs to control iTerm2 to bring its window to the front.</string>
</dict>
</plist>
PLIST

printf 'APPL????' > "$OUT/Contents/PkgInfo"
if [ -f "$ICNS" ]; then
    cp "$ICNS" "$OUT/Contents/Resources/warden.icns"
else
    echo "→ no icon at $ICNS (optional; pass --icon <file.icns>)"
fi

# ---- compile --------------------------------------------------------------
TMP_SWIFT="$(mktemp -t warden).swift"
trap 'rm -f "$TMP_SWIFT"' EXIT
sed "s|/Users/a67_68/projects/ti_extend|$REPO|g" "$SRC" > "$TMP_SWIFT"
if ! grep -q "let REPO = \"$REPO\"" "$TMP_SWIFT"; then
    echo "✗ REPO was not substituted - check the /Users/a67_68/projects/ti_extend placeholder in $SRC" >&2
    exit 2
fi

# SWIFTC_FLAGS is an escape hatch for restricted environments that need the
# clang module cache somewhere writable.  Normal use does not set it.
# shellcheck disable=SC2086
swiftc ${SWIFTC_FLAGS:-} -O -target arm64-apple-macos13.0 \
    -o "$OUT/Contents/MacOS/Warden" -framework Cocoa "$TMP_SWIFT"
[ -x "$OUT/Contents/MacOS/Warden" ] || { echo "✗ compile produced no executable" >&2; exit 2; }

# ---- sign (important, do not delete) --------------------------------------
# An unsigned app makes TCC refuse to remember any authorisation decision - the
# symptom is that no permission dialog even appears and you get -1743
# "not authorised to send Apple events", with nothing under Privacy > Automation.
# The designated requirement pins the identity to the identifier: an ad-hoc
# signature otherwise uses the cdhash, so every rebuild becomes "a different app"
# and all grants are void.
codesign --force --sign - \
    --identifier "$BUNDLE_ID" \
    --requirements "=designated => identifier \"$BUNDLE_ID\"" \
    "$OUT" 2>/dev/null || { echo "✗ codesign failed (a bad signature silently breaks TCC)" >&2; exit 2; }
if ! codesign --verify --verbose=2 "$OUT" >/dev/null 2>&1; then
    echo "✗ signature did not verify; TCC will refuse it. Better to stop here." >&2
    exit 2
fi

touch "$OUT"
/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister \
    -f "$OUT" >/dev/null 2>&1 || true

echo
echo "✓ built: $OUT"
echo
echo "  summon:  open -a \"$OUT\"                (focus if running, else create)"
echo "           Dock click / Command-Tab / tell application \"Warden\" to activate"
echo "           osascript \"$HERE/warden-summon.applescript\"      # works without the app too"
echo "  dry run: osascript \"$HERE/warden-summon.applescript\" --dry-run"
echo "  logs:    cat temp/warden-app.log temp/warden-summon.log"
